WITH exploded AS (SELECT id, plan, effective_from, EXPLODE(discounts) AS tier_value FROM price_tiers) SELECT CASE WHEN tier_value >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END AS tier_value_tier, COUNT(DISTINCT id) AS distinct_ids, COUNT(*) AS cnt, APPROX_PERCENTILE(tier_value, ARRAY(0.25, 0.5, 0.75)) AS tier_value_quartiles, COUNT(DISTINCT plan) AS distinct_plans, APPROX_PERCENTILE(tier_value, 0.95) AS tier_value_p95 FROM exploded GROUP BY CASE WHEN tier_value >= 84 THEN 'PREMIUM' ELSE 'STANDARD' END ORDER BY tier_value_p95 NULLS FIRST;
